57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /** Dedicated audit logger; a successful create emits one line here. */
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
70	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
113	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
114	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        HttpHeaders headers = new HttpHeaders();
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        String address = normalizeAddress(owner.getAddress());
123	        if (address.isEmpty()) {
124	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
125	        }
126	        owner.setAddress(address);
127	        if (owner.getEmail() != null) {
128	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
129	            if (!EMAIL_PATTERN.matcher(email).matches()) {
130	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	            }
132	            owner.setEmail(email);
133	        }
134	        String telephone = normalizeTelephone(owner.getTelephone());
135	        if (telephone == null) {
136	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
137	        }
138	        owner.setTelephone(telephone);
139	        LocalDate registrationDate = resolveRegistrationDate(owner.getRegistrationDate());
140	        owner.setRegistrationDate(registrationDate);
141	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
142	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
143	        }
144	        if (isTelephoneInUse(telephone)) {
145	            return new ResponseEntity<>(HttpStatus.CONFLICT);
146	        }
147	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()) && isHouseholdInUse(owner)) {
148	            return new ResponseEntity<>(HttpStatus.CONFLICT);
149	        }
150	        if (countOwnersInCity(owner.getCity()) >= 50) {
151	            return new ResponseEntity<>(HttpStatus.CONFLICT);
152	        }
153	        assignRegistrationAttributes(owner);
154	        this.clinicService.saveOwner(owner);
155	        AUDIT.info("Owner created id={} customerCode={} registrationDate={}",
156	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
157	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
158	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
159	        headers.setLocation(UriComponentsBuilder.newInstance()
160	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
161	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
167	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
168	        if (currentOwner == null) {
169	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
170	        }
171	        currentOwner.setAddress(ownerFieldsDto.getAddress());
172	        currentOwner.setCity(ownerFieldsDto.getCity());
173	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
174	        currentOwner.setLastName(ownerFieldsDto.getLastName());
175	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
176	        String email = ownerFieldsDto.getEmail();
177	        if (email != null) {
178	            email = email.trim().toLowerCase(Locale.ROOT);
179	            if (!EMAIL_PATTERN.matcher(email).matches()) {
180	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
181	            }
182	        }
183	        currentOwner.setEmail(email);
184	        this.clinicService.saveOwner(currentOwner);
185	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Transactional
190	    @Override
191	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
192	        Owner owner = this.clinicService.findOwnerById(ownerId);
193	        if (owner == null) {
194	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
195	        }
196	        this.clinicService.deleteOwner(owner);
197	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Override
202	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
203	        Owner owner = this.clinicService.findOwnerById(ownerId);
204	        if (owner == null) {
205	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
206	        }
207	        HttpHeaders headers = new HttpHeaders();
208	        Pet pet = petMapper.toPet(petFieldsDto);
209	        owner.setId(ownerId);
210	        pet.setOwner(owner);
211	        pet.getType().setName(null);
212	        this.clinicService.savePet(pet);
213	        PetDto petDto = petMapper.toPetDto(pet);
214	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
215	            .buildAndExpand(pet.getId()).toUri());
216	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
217	    }
218	
219	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
220	    @Override
221	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
222	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
223	        if (currentOwner != null) {
224	            Pet currentPet = this.clinicService.findPetById(petId);
225	            if (currentPet != null) {
226	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
227	                currentPet.setName(petFieldsDto.getName());
228	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
229	                this.clinicService.savePet(currentPet);
230	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
231	            }
232	        }
233	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
234	    }
235	
236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
239	        HttpHeaders headers = new HttpHeaders();
240	        Visit visit = visitMapper.toVisit(visitFieldsDto);
241	        Pet pet = new Pet();
242	        pet.setId(petId);
243	        visit.setPet(pet);
244	        this.clinicService.saveVisit(visit);
245	        VisitDto visitDto = visitMapper.toVisitDto(visit);
246	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
247	            .buildAndExpand(visit.getId()).toUri());
248	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
249	    }
250	
251	
252	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
253	    @Override
254	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
255	        Owner owner = this.clinicService.findOwnerById(ownerId);
256	        if (owner != null) {
257	            Pet pet = owner.getPet(petId);
258	            if (pet != null) {
259	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
260	            }
261	        }
262	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
263	    }
264	
265	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
266	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
267	
268	    /**
269	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
270	     * code are kept when present; otherwise country code '+61' is assumed and a single
271	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
272	     * stripped. The result must be a '+' followed by 8 to 15 digits.
273	     * Returns {@code null} when the number cannot form a valid E.164 value.
274	     */
275	    private static String normalizeTelephone(String telephone) {
276	        if (telephone == null) {
277	            return null;
278	        }
279	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
280	        String e164;
281	        if (cleaned.startsWith("+")) {
282	            e164 = cleaned;
283	        } else {
284	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
285	            e164 = "+61" + national;
286	        }
287	        return E164_PATTERN.matcher(e164).matches() ? e164 : null;
288	    }
289	
290	    /**
291	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
292	     * code, membership number, household id, namesake count and household member count. Each is
293	     * derived from the owner's already-normalized fields and the existing owner population, so this
294	     * must run before the owner is saved, while the counts still exclude the owner being created.
295	     */
296	    private void assignRegistrationAttributes(Owner owner) {
297	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
298	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
299	        owner.setHouseholdId(householdId(owner));
300	        owner.setNamesakeCount(countNamesakes(owner));
301	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
302	    }
303	
304	    /**
305	     * Build the customer code '<CITY3>-<LAST3>-<NNNN>': CITY3 is the upper-cased first three
306	     * letters of {@code city}, LAST3 the upper-cased first three letters of {@code lastName},
307	     * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
308	     * owners already registered in that city (e.g. 'SYD-SMI-0007').
309	     */
310	    private String generateCustomerCode(String city, String lastName) {
311	        String city3 = firstThreeLetters(city);
312	        String last3 = firstThreeLetters(lastName);
313	        int sequence = countOwnersInCity(city) + 1;
314	        return String.format("%s-%s-%04d", city3, last3, sequence);
315	    }
316	
317	    /** The upper-cased first three letters (ignoring non-letters) of {@code value}. */
318	    private static String firstThreeLetters(String value) {
319	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
320	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
321	    }
322	
323	    /**
324	     * The number of existing owners registered in {@code city}, compared case-insensitively
325	     * with collapsed whitespace.
326	     */
327	    private int countOwnersInCity(String city) {
328	        String normalized = normalizeHouseholdField(city);
329	        return (int) this.clinicService.findAllOwners().stream()
330	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
331	            .count();
332	    }
333	
334	    /**
335	     * The effective registration date to store for a new owner: the date supplied on the request
336	     * when present, otherwise the current server date, in either case rolled forward to a business
337	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
338	     * This single point of resolution is what every registration-date-derived value (the stored
339	     * date, the membership number's year segment, the per-day create-limit) is computed from.
340	     */
341	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
342	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
343	        return toBusinessDay(date);
344	    }
345	
346	    /**
347	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
348	     * following Monday; a weekday is returned unchanged.
349	     */
350	    private static LocalDate toBusinessDay(LocalDate date) {
351	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
352	            date = date.plusDays(1);
353	        }
354	        return date;
355	    }
356	
357	    /**
358	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
359	     * {@code registrationDate} year (e.g. 'SMI-0007-M26').
360	     */
361	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
362	        String yy = String.format("%02d", registrationDate.getYear() % 100);
363	        return customerCode + "-M" + yy;
364	    }
365	
366	    /**
367	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
368	     * last name, compared case-insensitively.
369	     */
370	    private int countNamesakes(Owner owner) {
371	        String firstName = normalizeHouseholdField(owner.getFirstName());
372	        String lastName = normalizeHouseholdField(owner.getLastName());
373	        return (int) this.clinicService.findAllOwners().stream()
374	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
375	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
376	            .count();
377	    }
378	
379	    /**
380	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
381	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
382	     * unusually high daily signup volume.
383	     */
384	    private boolean isBulkSignupWarning() {
385	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
386	    }
387	
388	    /** The number of existing owners whose registration date is {@code date}. */
389	    private int countOwnersRegisteredOn(LocalDate date) {
390	        return (int) this.clinicService.findAllOwners().stream()
391	            .filter(existing -> date.equals(existing.getRegistrationDate()))
392	            .count();
393	    }
394	
395	    /** Whether any existing owner already uses the given (E.164) telephone number. */
396	    private boolean isTelephoneInUse(String telephone) {
397	        return this.clinicService.findAllOwners().stream()
398	            .map(Owner::getTelephone)
399	            .filter(existing -> existing != null)
400	            .map(OwnerRestControllerV1::normalizeTelephone)
401	            .filter(existing -> existing != null)
402	            .anyMatch(telephone::equals);
403	    }
404	
405	    /** Common street-type abbreviations expanded during address normalization. */
406	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
407	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
408	
409	    /**
410	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
411	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
412	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
413	     * string when {@code address} is null or blank after normalization.
414	     */
415	    private static String normalizeAddress(String address) {
416	        if (address == null) {
417	            return "";
418	        }
419	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
420	        if (collapsed.isEmpty()) {
421	            return "";
422	        }
423	        StringBuilder sb = new StringBuilder(collapsed.length());
424	        for (String token : collapsed.split(" ")) {
425	            if (sb.length() > 0) {
426	                sb.append(' ');
427	            }
428	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
429	        }
430	        return sb.toString();
431	    }
432	
433	    /**
434	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
435	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
436	     */
437	    private static String normalizeHouseholdField(String value) {
438	        if (value == null) {
439	            return "";
440	        }
441	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
442	    }
443	
444	    /**
445	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
446	     * same address compared case-insensitively with collapsed whitespace.
447	     */
448	    private List<Owner> findHousemates(Owner owner) {
449	        String lastName = normalizeHouseholdField(owner.getLastName());
450	        String address = normalizeHouseholdField(owner.getAddress());
451	        return this.clinicService.findAllOwners().stream()
452	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
453	                && normalizeHouseholdField(existing.getAddress()).equals(address))
454	            .toList();
455	    }
456	
457	    /**
458	     * Whether any existing owner already shares the same household as {@code owner}, i.e. has the
459	     * same last name AND the same address compared case-insensitively with collapsed whitespace.
460	     */
461	    private boolean isHouseholdInUse(Owner owner) {
462	        return !findHousemates(owner).isEmpty();
463	    }
464	
465	    /**
466	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
467	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself. A value of
468	     * 3 or more raises the membership tier to GOLD.
469	     */
470	    private int countHouseholdMembers(Owner owner) {
471	        return findHousemates(owner).size() + 1;
472	    }
473	
474	    /**
475	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
476	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
477	     * deterministically from those normalized fields so housemates always resolve to the same value,
478	     * regardless of registration order.
479	     */
480	    private static String householdId(Owner owner) {
481	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
482	            + normalizeHouseholdField(owner.getAddress());
483	        try {
484	            byte[] digest = MessageDigest.getInstance("SHA-256")
485	                .digest(key.getBytes(StandardCharsets.UTF_8));
486	            StringBuilder sb = new StringBuilder(24);
487	            for (int i = 0; i < 12; i++) {
488	                sb.append(String.format("%02X", digest[i]));
489	            }
490	            return sb.toString();
491	        }
492	        catch (NoSuchAlgorithmException e) {
493	            throw new IllegalStateException("SHA-256 not available", e);
494	        }
495	    }
